void NGLScene::keyPressEvent(QKeyEvent *_event)
{
  // this method is called every time the main window recives a key event.
  // we then switch on the key value and set the camera in the GLWindow
  switch (_event->key())
  {
  // escape key to quite
  case Qt::Key_Escape:
    QGuiApplication::exit(EXIT_SUCCESS);
    break;
  // show full screen
  case Qt::Key_F:
    showFullScreen();
    break;
  // show windowed
  case Qt::Key_N:
    showNormal();
    break;
  case Qt::Key_Q:
    changeWeight(Weights::POSE1, Direction::DOWN);
    break;
  case Qt::Key_W:
    changeWeight(Weights::POSE1, Direction::UP);
    break;

  case Qt::Key_A:
    changeWeight(Weights::POSE2, Direction::DOWN);
    break;
  case Qt::Key_S:
    changeWeight(Weights::POSE2, Direction::UP);
    break;
  case Qt::Key_Space:
    toggleAnimation();
    break;
  case Qt::Key_Z:
    punchLeft();
    break;
  case Qt::Key_X:
    punchRight();
    break;

  default:
    break;
  }
  // finally update the GLWindow and re-draw
  // if (isExposed())
  update();
}

void NGLScene::updateLeft()
{
  static Direction left = Direction::UP;
  if (left == Direction::UP)
  {
    m_weight1 += 0.2f;
    if (m_weight1 > 1.1f)
      left = Direction::DOWN;
  }
  else if (left == Direction::DOWN)
  {
    m_weight1 -= 0.2f;
    if (m_weight1 <= 0.0f)
    {
      m_weight1 = 0.0f;

      m_timerLeft->stop();
      left = Direction::UP;
      m_punchLeft = false;
    }
  }
  update();
}

void NGLScene::updateRight()
{
  static Direction right = Direction::UP;
  if (right == Direction::UP)
  {
    m_weight2 += 0.2f;
    if (m_weight2 > 1.1f)
      right = Direction::DOWN;
  }
  else if (right == Direction::DOWN)
  {
    m_weight2 -= 0.2f;
    if (m_weight2 <= 0.0f)
    {
      m_weight2 = 0.0f;
      m_timerRight->stop();
      right = Direction::UP;
      m_punchRight = false;
    }
  }
  update();
}

