#ifndef ABSTRACTOCTREE_H_
#define ABSTRACTOCTREE_H_
#include <vector>
#include <iostream>
#include <array>
#include <ngl/Vec2.h>
#include <ngl/Vec3.h>
#include <ngl/Vec4.h>
