                 t.getMatrix();

    normalMatrix.inverse().transpose();
    ngl::ShaderLib::setUniform("MVP",MVP);
    ngl::ShaderLib::setUniform("normalMatrix",normalMatrix);


    // get an instance of the VBO primitives for drawing
    ngl::VAOPrimitives::draw("sphere");

}


