layout(location = 0) in vec3 baseVert;
layout(location = 1) in vec3 baseNormal;
layout(location = 2) in vec3 poseVert1;
layout(location = 3) in vec3 poseNormal1;
layout(location = 4) in vec3 poseVert2;
layout(location = 5) in vec3 poseNormal2;

uniform mat4 MVP;
uniform mat4 MV;
uniform mat3 normalMatrix;
uniform float weight1;
uniform float weight2;

out vec3 eyePosition;
out vec3 eyeNormal;

void main()
{
  vec3 finalPosition = baseVert + weight1 * poseVert1 + weight2 * poseVert2;
  vec3 finalNormal = baseNormal + weight1 * poseNormal1 + weight2 * poseNormal2;
  eyePosition = vec3(MV * vec4(finalPosition, 1.0));
  eyeNormal = normalize(normalMatrix * finalNormal);
  gl_Position = MVP * vec4(finalPosition, 1.0);
}

struct Uniforms {
  mvp: mat4x4<f32>,
  model_view: mat4x4<f32>,
  normal_matrix: mat4x4<f32>,
  light_position: vec4<f32>,
  weights: vec4<f32>,
};

@group(0) @binding(0) var<uniform> uniforms: Uniforms;

struct VertexOutput {
  @builtin(position) position: vec4<f32>,
  @location(0) eye_position: vec3<f32>,
  @location(1) eye_normal: vec3<f32>,
};

@vertex
fn vertex_main(
  @location(0) base_position: vec3<f32>,
  @location(1) base_normal: vec3<f32>,
  @location(2) pose_position_one: vec3<f32>,
  @location(3) pose_normal_one: vec3<f32>,
  @location(4) pose_position_two: vec3<f32>,
  @location(5) pose_normal_two: vec3<f32>,
) -> VertexOutput {
  let final_position = base_position
    + uniforms.weights.x * pose_position_one
    + uniforms.weights.y * pose_position_two;
  let final_normal = base_normal
    + uniforms.weights.x * pose_normal_one
    + uniforms.weights.y * pose_normal_two;
  var output: VertexOutput;
  output.position = uniforms.mvp * vec4<f32>(final_position, 1.0);
  output.eye_position = (uniforms.model_view * vec4<f32>(final_position, 1.0)).xyz;
  output.eye_normal = normalize((uniforms.normal_matrix * vec4<f32>(final_normal, 0.0)).xyz);
  return output;
}

@fragment
fn fragment_main(input: VertexOutput) -> @location(0) vec4<f32> {
  let normal = normalize(input.eye_normal);
  let light_direction = normalize(uniforms.light_position.xyz - input.eye_position);
  let view_direction = normalize(-input.eye_position);
  let half_vector = normalize(light_direction + view_direction);
  let diffuse = max(dot(normal, light_direction), 0.0);
  var specular = 0.0;
  if diffuse > 0.0 {
    specular = pow(max(dot(normal, half_vector), 0.0), 64.0);
  }
  let colour = vec3<f32>(0.08) + vec3<f32>(0.72) * diffuse + vec3<f32>(0.35) * specular;
  return vec4<f32>(colour, 1.0);
}

#version 410 core

in vec3 eyePosition;
in vec3 eyeNormal;
layout(location = 0) out vec4 fragColour;

uniform vec3 lightPosition;

void main()
{
  vec3 normal = normalize(eyeNormal);
  vec3 lightDirection = normalize(lightPosition - eyePosition);
  vec3 viewDirection = normalize(-eyePosition);
  vec3 halfVector = normalize(lightDirection + viewDirection);
  float diffuse = max(dot(normal, lightDirection), 0.0);
  float specular = diffuse > 0.0 ? pow(max(dot(normal, halfVector), 0.0), 64.0) : 0.0;
  vec3 colour = vec3(0.08) + vec3(0.72) * diffuse + vec3(0.35) * specular;
  fragColour = vec4(colour, 1.0);
}

